"""Small resilient client for the local order service (working script, not a deliverable)."""
import json
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
LOGFILE = "/tmp/recon/events.log"

_token = None
stats = {"requests": 0, "tokens": 0, "retries_429": 0, "retries_401": 0, "retries_other": 0}


def log(msg):
    line = time.strftime("%H:%M:%S") + " " + msg
    print(line, flush=True)
    with open(LOGFILE, "a") as fh:
        fh.write(line + "\n")


def new_token():
    global _token
    req = urllib.request.Request(BASE + "/token", data=b"", method="POST")
    with urllib.request.urlopen(req, timeout=30) as resp:
        body = json.loads(resp.read().decode())
    _token = body["token"]
    stats["tokens"] += 1
    log("new token: %s" % _token)
    return _token


def _raw_get(path):
    """Return (status, headers, body_bytes) without raising on HTTP errors."""
    headers = {"Authorization": "Bearer " + _token}
    req = urllib.request.Request(BASE + path, headers=headers, method="GET")
    stats["requests"] += 1
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, dict(resp.headers), resp.read()
    except urllib.error.HTTPError as err:
        return err.code, dict(err.headers), err.read()


def _wait_hint(headers, body):
    """Seconds the server asked us to wait, from Retry-After or the JSON body."""
    for key, val in headers.items():
        if key.lower() == "retry-after":
            try:
                return float(val)
            except ValueError:
                pass
    try:
        data = json.loads(body.decode())
    except Exception:
        return None
    if isinstance(data, dict):
        for key in ("retry_after", "retry_after_seconds", "wait", "wait_seconds", "retryAfter"):
            if key in data:
                try:
                    return float(data[key])
                except (TypeError, ValueError):
                    pass
    return None


def get_json(path, accept_404=False, max_attempts=60):
    """GET path with auth; handles 429 (wait as told), expired tokens, transient errors."""
    global _token
    for attempt in range(1, max_attempts + 1):
        if _token is None:
            new_token()
        try:
            status, headers, body = _raw_get(path)
        except Exception as exc:  # network-level failure: repeat the request
            stats["retries_other"] += 1
            log("%s attempt %d: transport error %r, retrying" % (path, attempt, exc))
            time.sleep(1)
            continue

        if status == 200:
            try:
                return json.loads(body.decode())
            except Exception:
                stats["retries_other"] += 1
                log("%s attempt %d: 200 but body not JSON (%r), retrying" % (path, attempt, body[:200]))
                time.sleep(1)
                continue

        if status == 404 and accept_404:
            return None

        if status == 429:
            stats["retries_429"] += 1
            wait = _wait_hint(headers, body)
            log("%s attempt %d: 429 headers=%r body=%r -> wait=%r" % (path, attempt, headers, body[:300], wait))
            time.sleep((wait if wait is not None else 5) + 0.25)
            continue

        if status in (401, 403):
            stats["retries_401"] += 1
            log("%s attempt %d: %d headers=%r body=%r -> refreshing token" % (path, attempt, status, headers, body[:300]))
            _token = None
            continue

        stats["retries_other"] += 1
        log("%s attempt %d: HTTP %d headers=%r body=%r, retrying" % (path, attempt, status, headers, body[:300]))
        time.sleep(1)

    raise RuntimeError("gave up on %s after %d attempts" % (path, max_attempts))

